def _merge_currency(*lists):
    """把 [(currency, amount), ...] 多组按币种合并，不跨币种相加。"""
    d: dict[str, float] = {}
    for lst in lists:
        for c, amt in lst:
            c = c or "THB"
            d[c] = d.get(c, 0) + float(amt or 0)
    return [{"currency": c, "amount": round(v, 2)} for c, v in sorted(d.items())]

