def positive_money(value):
    try:
        n = Decimal(str(value))
        if not n.is_finite() or n <= 0 or n != money(n) or n >= Decimal('1000000000000'):
            raise ValueError
        return n
    except (ValueError, InvalidOperation):
        raise HTTPException(400, '金额必须大于0，且最多两位小数')

