def validate_amount(value):
    try:
        raw = Decimal(str(value))
        rounded = money(raw)
        if not raw.is_finite() or rounded <= 0 or rounded >= Decimal("1000000000000") or abs(raw - rounded) > Decimal("0.00000001"):
            raise ValueError
        return rounded
    except (ValueError, InvalidOperation):
