@router.post("/review/batch")
async def batch_review(
    req: BatchReviewReq,
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db),
    _perm=Depends(check_staff_permission("备用金管理")),
):
    if current_user.role == Role.SUPER_ADMIN:
        raise HTTPException(403, "超级管理员请使用各仓库管理员账号操作")
    if current_user.role not in (Role.SUPER_ADMIN, Role.WAREHOUSE_ADMIN, Role.SUPERVISOR, Role.STAFF):
        raise HTTPException(403, "无审核权限")

    new_status = "approved" if req.action == "approve" else "rejected"
    wh_ids = get_wh_ids(current_user)
    processed = 0

    warehouses=(await db.execute(select(ExpenseFund.warehouse_id).join(ExpenseFundItem,ExpenseFundItem.fund_id==ExpenseFund.id)
        .where(ExpenseFundItem.id.in_(req.item_ids),ExpenseFund.warehouse_id.in_(wh_ids)).distinct())).scalars().all()
    for wid in sorted(warehouses):await costs.lock(db,wid)

    for item_id in req.item_ids:
        item = (await db.execute(select(ExpenseFundItem).where(ExpenseFundItem.id == item_id))).scalar_one_or_none()
        if not item: continue
        # 校验仓库归属：只处理当前用户能管仓库的开销，其他仓库跳过
        fund_wh = (await db.execute(select(ExpenseFund.warehouse_id).where(ExpenseFund.id == item.fund_id))).scalar_one_or_none()
        if fund_wh is None or fund_wh not in wh_ids:
            continue
        from app.models import ExpenseApproval
        if (await db.execute(select(ExpenseApproval.id).where(ExpenseApproval.fund_item_id==item_id).limit(1))).first():
            raise HTTPException(400,'费用审批联动开销请在原费用审批处理，不能独立改审或释放费用身份')
        # 新预支的资金事实只能随预支作废撤回，不能从开销审核绕过预支权限。
        from app.models.employee_advance import EmployeeAdvance
        if (await db.execute(select(EmployeeAdvance.id).where(
            EmployeeAdvance.fund_item_id == item_id, EmployeeAdvance.funding_source == "expense_fund",
            EmployeeAdvance.not_voided(),
        ).limit(1))).first():
            raise HTTPException(400, "员工预支关联开销请在员工预支中处理")
        # 与报销付款/撤销按相同顺序锁行；原扣款、退款金额和审批规则不变。
        linked_reimb = None
        if item.category == "报销":
            linked_reimb = (await db.execute(select(Reimbursement).where(
                Reimbursement.fund_item_id == item_id, Reimbursement.is_fund_linked == "1",
            ).with_for_update())).scalar_one_or_none()
        item = (await db.execute(select(ExpenseFundItem).where(ExpenseFundItem.id == item_id)
            .with_for_update().execution_options(populate_existing=True))).scalar_one_or_none()
        if item is None:
            continue
        if item.is_voided:
            raise HTTPException(400, "该开销已作废，不能审核")
        old_status = item.review_status
        # 幂等守卫：状态未变化则跳过，避免重复驳回导致余额被多次退回
        if old_status == new_status:
            continue
        # 报销自动生成的台账保留原报销审核路径；手工登记开销即使类别写“报销”也不能绕过。
        if req.action == "approve" and linked_reimb is None and not (item.receipt or "").strip():
            raise HTTPException(400, f"该开销没有凭证，请先上传开销凭证（开销 #{item.id}）")
        item.review_status = new_status
        item.review_remark = req.remark
        if item_id not in await item_controls.linked_ids(db,[item_id]):
            await costs.sync(db,'fund_item',item,current_user,skip_suspicion=req.action!='approve',
                confirmation=(req.cost_confirmations or {}).get(item_id,req.cost_confirmation))
        processed += 1

        # Sync with linked reimbursement（仅在状态真正发生变化时执行一次）
        if item.category == "报销":
            reimb = linked_reimb
            if reimb:
                if req.action == "approve":
                    reimb.status = ReimbStatus.PAID.value
                    reimb.paid_at = datetime.utcnow()
                    from app.services.reimbursement_payment import sync_fund_review_payment
                    await sync_fund_review_payment(db, reimb, current_user, approved=True)
                elif req.action == "reject":
                    # Restore balance and unlock reimbursement（仅当之前不是已驳回）
                    from app.services.flow_rules import can_refund_fund_item
                    if can_refund_fund_item(old_status):
                        fund = (await db.execute(select(ExpenseFund).where(ExpenseFund.id == item.fund_id))).scalar_one_or_none()
                        if fund:
                            fund.remaining_balance = (fund.remaining_balance or 0) + item.amount
                    reimb.status = ReimbStatus.PENDING.value
                    reimb.is_fund_linked = "0"
                    from app.services.reimbursement_payment import sync_fund_review_payment
                    await sync_fund_review_payment(db, reimb, current_user, approved=False, reason=req.remark)

    await db.flush()

    labels = {"approve": "通过", "reject": "驳回"}
    return {"message": f"已{labels.get(req.action, req.action)}{processed}条记录"}

