async def payroll_usage_totals(db, advances):
    if not advances:
        return {}
    warehouses = {a.id: a.warehouse_id for a in advances}
    totals = {a.id: Decimal("0.00") for a in advances}
    rows = (await db.execute(select(
        PayrollRecord.cash_advance_id, PayrollRecord.warehouse_id, PayrollRecord.net_pay,
    ).where(
        PayrollRecord.cash_advance_id.in_(warehouses),
        PayrollRecord.disbursed.is_(True), PayrollRecord.voided.is_not(True),
    ))).all()
    for advance_id, warehouse_id, amount in rows:
        if warehouses[advance_id] == warehouse_id:
            totals[advance_id] += Decimal(str(amount)).quantize(Decimal("0.01"))
    return totals

async def reimbursement_usage_totals(db, advances):
    if not advances:
        return {}
    rows = (await db.execute(select(
        ReimbursementPayment.cash_advance_id, func.sum(ReimbursementPayment.amount),
    ).where(
        ReimbursementPayment.cash_advance_id.in_([a.id for a in advances]),
        ReimbursementPayment.status == "active", ReimbursementPayment.funding_source == "cash_advance",
    ).group_by(ReimbursementPayment.cash_advance_id))).all()
    amounts = dict(rows)
    return {a.id: Decimal(str(amounts.get(a.id) or 0)) for a in advances}

