            'currency':currency,'action':'关联唯一实际到账，不另增一次实收'},warehouse_id=c.warehouse_id)
    debt = await refresh_debt(db,c)
    return {'id':rid,'incoming_flow_id':flow.id,**debt,'message':'回款已关联实际到账，同笔资金只计一次'}

