@router.post("/image")
async def upload_market_image(file: UploadFile = File(...), warehouse_id: int = Form(...),
    current_user: User = Depends(require_role(Role.SUPER_ADMIN)), db: AsyncSession = Depends(get_db)):
    import uuid
