def parse_hhmm(s) -> time | None:
    """把 'HH:MM' 解析为 time；无效返回 None。"""
    if not isinstance(s, str):
        return None
    try:
        return datetime.strptime(s.strip(), "%H:%M").time()
    except (ValueError, TypeError):
        return None

