def _fmt_hours(h: float) -> str:
    """小时数格式化为字符串：整数不留小数，最多保留 2 位小数。"""
    if h is None:
        return ""
    h2 = round(float(h), 2)
    if h2 == int(h2):
        return str(int(h2))
    return f"{h2:.2f}".rstrip("0").rstrip(".")

