            key="overtime_monthly_limit",
            value=str(req.max_hours),
            updated_by=current_user.id,
        )
        db.add(setting)

    await db.flush()
    return {"message": f"加班上限已设为 {req.max_hours:.0f} 小时/月", "max_hours": req.max_hours}

