async def _prepare_payroll(db: AsyncSession, current_user: User, wh_id: int, req: CalculateRequest) -> dict:
    """准备阶段（不写任何数据）：确定结束日、查员工、算水位线/起点、校验、查待补打卡。
    返回计算所需的所有数据 + 检查结果，供 _calc_payroll 和预览接口共用。"""
    today = thai_today()
    yesterday = today - timedelta(days=1)
    cap_note = ""

    # ── 1. 确定结算结束日：新 end_date 优先；旧 period+half 兼容换算 ──
    if req.end_date:
        try:
            batch_end = datetime.strptime(req.end_date, "%Y-%m-%d").date()
        except (ValueError, TypeError):
            raise HTTPException(400, "结束日格式错误，应为 YYYY-MM-DD")
        if req.is_resignation:
            if batch_end > today:
                raise HTTPException(400, "离职日不能选未来")
            if batch_end == today:
                raise HTTPException(400, "离职日不能是今天，今天还没过完，请让员工第二天来办离职，给仓库一天缓冲期把账算清")
        else:
            if batch_end > today:
                raise HTTPException(400, "结束日不能选未来")
            if batch_end == today:
                batch_end = yesterday
                cap_note = f"今天还没过完，本次算到 {batch_end.isoformat()}"
    else:
        try:
            y, m = req.period.split("-")
            year, month = int(y), int(m)
        except (ValueError, TypeError, AttributeError):
            raise HTTPException(400, "月份格式错误，应为 YYYY-MM")
        if month < 1 or month > 12:
            raise HTTPException(400, "月份无效")
        _, _td = calendar.monthrange(year, month)
        computed_end = date(year, month, 15 if req.half == "first_half" else _td)
        if computed_end > yesterday:
            batch_end = yesterday
            cap_note = f"今天还没过完，本次算到 {batch_end.isoformat()}"
        else:
            batch_end = computed_end

    year, month = batch_end.year, batch_end.month
    _, total_days = calendar.monthrange(year, month)
    period = batch_end.strftime("%Y-%m")
    half = "first_half" if batch_end.day <= 15 else "second_half"

    base = {
        "batch_end": batch_end, "cap_note": cap_note, "period": period, "half": half, "total_days": total_days,
        "employees": [], "emp_start": {}, "skipped_notes": [],
        "no_hire_names": [], "no_salary_template": [], "no_deduction_template": [], "pending_days": [],
        "grace_days": [],
    }

    # ── 2. 在职员工（排除已删除/离职），单人可限定；重算模式取指定员工（含离职/已删除）──
    recalc_mode = req.recalc_employee_id is not None
    if recalc_mode:
        emp = (await db.execute(
            select(Employee).where(
                Employee.id == req.recalc_employee_id,
                Employee.warehouse_id == wh_id,
            )
        )).scalar_one_or_none()
        if not emp:
            raise HTTPException(404, "员工不存在")
        employees = [emp]
    else:
        emp_q = select(Employee).where(
            Employee.warehouse_id == wh_id,
            Employee.status != "resigned",
            Employee.is_deleted == False,
        )
        if req.employee_ids:
            emp_q = emp_q.where(Employee.id.in_(req.employee_ids))
        employees = (await db.execute(emp_q)).scalars().all()

    owners, _ = await employee_account_roles(db, employees)
    employees = [emp for emp in employees if not (
        emp.position in ("仓库主管", "仓库管理员")
        and owners.get(emp.id) is not None
        and owners[emp.id].role in ("supervisor", "warehouse_admin")
        and owners[emp.id].warehouse_id == emp.warehouse_id
        and not owners[emp.id].attendance_enabled
    )]

    if not employees:
        msg = "该仓库没有可结算的在职员工"
        if cap_note:
            msg += "；" + cap_note
        base["early_return"] = {"message": msg, "records": [], "skipped": []}
        return base

    # ── 3. 水位线 = 该员工已结算结束日的最大值（排除已作废；重算模式不走水位线）──
    emp_ids = [e.id for e in employees]
    water_line = {}
    if emp_ids and not recalc_mode:
        emp_records = (await db.execute(
            select(PayrollRecord).where(
                PayrollRecord.warehouse_id == wh_id,
                PayrollRecord.employee_id.in_(emp_ids),
                PayrollRecord.voided == False,
            )
        )).scalars().all()
        for r in emp_records:
            wl = r.settle_end_date
            if wl is None:
                try:
                    ry, rm = r.period.split("-")
                    wl = date(int(ry), int(rm), 15 if r.half == "first_half" else calendar.monthrange(int(ry), int(rm))[1])
                except (ValueError, TypeError, AttributeError):
                    wl = None
            if wl and (water_line.get(r.employee_id) is None or wl > water_line[r.employee_id]):
                water_line[r.employee_id] = wl

    # ── 4. 每个员工的起点 = 水位线+1 或 入职日期（重算模式用写死起点）──
    emp_start = {}
    no_hire_names = []
    skipped_notes = []
    if recalc_mode:
        try:
            recalc_start = datetime.strptime(req.recalc_start_date, "%Y-%m-%d").date()
        except (ValueError, TypeError):
            raise HTTPException(400, "开始日格式错误，应为 YYYY-MM-DD")
    else:
        recalc_start = None
    for emp in employees:
        if recalc_mode:
            start = recalc_start
        else:
            wl = water_line.get(emp.id)
            if wl:
                start = wl + timedelta(days=1)
            else:
                hd = emp.hire_date
                if not hd:
                    no_hire_names.append(emp.name)
                    continue
                start = hd.date() if isinstance(hd, datetime) else hd
        if start > batch_end:
            if recalc_mode:
                raise HTTPException(400, "结算开始日晚于结束日，无法重算")
            if wl:
                skipped_notes.append(f"{emp.name} 已结算到 {wl.isoformat()}，没有需要结算的区间")
            else:
                skipped_notes.append(f"{emp.name} 入职日期 {start.isoformat()} 晚于结束日，没有需要结算的区间")
            continue
        emp_start[emp.id] = start

    employees = [e for e in employees if e.id in emp_start]
    if not employees:
        base["emp_start"] = emp_start
        base["skipped_notes"] = skipped_notes
        base["no_hire_names"] = no_hire_names
        if not no_hire_names:
            # 没有缺入职日期的，才走「全都已结清」；否则交给算工资那边先报缺入职日期
            if req.employee_ids and len(req.employee_ids) == 1:
                msg = "；".join(skipped_notes)
            else:
                msg = "所有员工都已经结算到这个日期了"
            if cap_note:
                msg += "；" + cap_note
            base["early_return"] = {"message": msg, "records": [], "skipped": skipped_notes, "record_count": 0}
        return base

    # ── 5. 模板检查 ──
    no_salary_template = [e for e in employees if not e.salary_template_id]
    no_deduction_template = [e for e in employees if not e.deduction_template_id]

    template_ids = {e.salary_template_id for e in employees if e.salary_template_id}
    template_map = {}
    if template_ids:
        ts = (await db.execute(select(SalaryTemplate).where(SalaryTemplate.id.in_(template_ids)))).scalars().all()
        template_map = {t.id: t for t in ts}

    dt_ids = {e.deduction_template_id for e in employees if e.deduction_template_id}
    deduction_template_map = {}
    if dt_ids:
        dts = (await db.execute(select(DeductionTemplate).where(DeductionTemplate.id.in_(dt_ids)))).scalars().all()
        deduction_template_map = {t.id: t for t in dts}

    work_sched = await get_work_schedule(db, wh_id)
    early_half_time = _parse_hhmm(work_sched["early_half"]) or time(17, 30)
    early_one_time = _parse_hhmm(work_sched["early_one"]) or time(17, 0)
    afternoon_end_time = _parse_hhmm(work_sched["afternoon_end"]) or time(18, 0)
    standard_hours = _standard_daily_hours(work_sched)

    # ── 6. 批量取数用最宽区间 ──
    period_start = min(emp_start.values())
    period_end = batch_end

    from app.services.employee_match import resolve_employee_user_map
    emp_user_map, user_emp_map = await resolve_employee_user_map(db, employees)
    emp_id_set = {e.id for e in employees}
    all_user_ids = list(user_emp_map.keys())

    clock_records = []
    if all_user_ids:
        clock_records = (await db.execute(
            select(ClockInRecord).where(
                ClockInRecord.clock_date >= period_start,
                ClockInRecord.clock_date <= period_end,
                ClockInRecord.user_id.in_(all_user_ids),
            ).order_by(ClockInRecord.clock_date, ClockInRecord.session)
        )).scalars().all()

    clock_by_emp_date = {}
    for cr in clock_records:
        eid = user_emp_map.get(cr.user_id)
        if not eid:
            continue
        key = (eid, cr.clock_date)
        if key not in clock_by_emp_date:
            clock_by_emp_date[key] = []
        clock_by_emp_date[key].append(cr)

    leaves = (await db.execute(
        select(LeaveRequest).where(
            LeaveRequest.employee_id.in_(emp_id_set),
            LeaveRequest.leave_date >= period_start,
            LeaveRequest.leave_date <= period_end,
            LeaveRequest.status == "approved",
        )
    )).scalars().all()
    leave_by_emp = {}
    for lv in leaves:
        if lv.employee_id not in leave_by_emp:
            leave_by_emp[lv.employee_id] = {}
        info = leave_by_emp[lv.employee_id].setdefault(
            lv.leave_date,
            {"full": False, "morning": False, "afternoon": False, "hours": 0.0, "hours_has": False, "notified_at": None},
        )
        dt = lv.duration_type or "full"
        if dt == "full":
            info["full"] = True
        elif dt == "morning":
            info["morning"] = True
        elif dt == "afternoon":
            info["afternoon"] = True
        elif dt == "hours":
            if lv.hours is None:
                info["full"] = True
                info["hourly_missing"] = True  # 小时数为空 → 按全天假处理，不报错
            else:
                info["hours"] += float(lv.hours)  # 一天多条按小时请假相加
                info["hours_has"] = True
        if lv.notified_at is not None and (info["notified_at"] is None or lv.notified_at < info["notified_at"]):
            info["notified_at"] = lv.notified_at

    rests = (await db.execute(
        select(RestDay).where(
            RestDay.employee_id.in_(emp_id_set),
            RestDay.rest_date >= period_start,
            RestDay.rest_date <= period_end,
        )
    )).scalars().all()
    rest_by_emp = {}
    for r in rests:
        if r.employee_id not in rest_by_emp:
            rest_by_emp[r.employee_id] = set()
        rest_by_emp[r.employee_id].add(r.rest_date)

    absences = (await db.execute(
        select(Absence).where(
            Absence.employee_id.in_(emp_id_set),
            Absence.absence_date >= period_start,
            Absence.absence_date <= period_end,
        )
    )).scalars().all()
    absence_by_emp = {}
    for a in absences:
        if a.employee_id not in absence_by_emp:
            absence_by_emp[a.employee_id] = set()
        absence_by_emp[a.employee_id].add(a.absence_date)

    overtime_rows = (await db.execute(
        select(
            OvertimeAssignment.employee_id,
            OvertimeTask.date,
            OvertimeAssignment.earned_amount,
            OvertimeTask.hours,
        )
        .join(OvertimeTask, OvertimeTask.id == OvertimeAssignment.overtime_id)
        .where(
            OvertimeAssignment.employee_id.in_(emp_id_set),
            OvertimeAssignment.confirmed == True,
            OvertimeTask.date >= period_start,
            OvertimeTask.date <= period_end,
        )
    )).all()
    overtime_map = {}
    for eid, od, amount, hours in overtime_rows:
        if od < emp_start[eid] or od > period_end:
            continue
        m = overtime_map.setdefault(eid, {"amount": 0.0, "hours": 0.0})
        m["amount"] = round((m["amount"] or 0) + (amount or 0), 2)
        m["hours"] = round((m["hours"] or 0) + (hours or 0), 1)

    fixed_rows = (await db.execute(
        select(EmployeeFixedDeduction).where(EmployeeFixedDeduction.employee_id.in_(emp_id_set))
    )).scalars().all()
    fixed_by_emp = {}
    for f in fixed_rows:
        fixed_by_emp.setdefault(f.employee_id, []).append({"id": f.id, "name": f.name, "amount": f.amount or 0})

    temp_rows = (await db.execute(
        select(EmployeeDeduction).where(
            EmployeeDeduction.employee_id.in_(emp_id_set),
            EmployeeDeduction.deduction_date >= period_start,
            EmployeeDeduction.deduction_date <= period_end,
        )
    )).scalars().all()
    temp_by_emp = {}
    for d in temp_rows:
        if d.deduction_date < emp_start[d.employee_id] or d.deduction_date > period_end:
            continue
        temp_by_emp.setdefault(d.employee_id, []).append({
            "id": d.id, "amount": d.amount or 0,
            "date": d.deduction_date.isoformat() if d.deduction_date else None,
            "reason": d.reason,
        })

    # ── 7. 待补打卡检查 + 宽限期统计 ──
    # 员工补卡次数（按天去重）：判断待补天是否因次数用完而不再拦
    emp_makeup_dates = {}
    if all_user_ids:
        makeup_records = (await db.execute(
            select(ClockInRecord).where(
                ClockInRecord.user_id.in_(all_user_ids),
                ClockInRecord.warehouse_id == wh_id,
                ClockInRecord.is_makeup == True,
            )
        )).scalars().all()
        for mr in makeup_records:
            eid = user_emp_map.get(mr.user_id)
            if eid:
                emp_makeup_dates.setdefault(eid, set()).add(mr.clock_date)

    pending_days = []
    grace_days = []
    for emp in employees:
        rest_set = rest_by_emp.get(emp.id, set())
        absence_set = absence_by_emp.get(emp.id, set())
        leave_map = leave_by_emp.get(emp.id, {})
        current = emp_start[emp.id]
        while current <= period_end:
            if current >= today:
                break
            if current in rest_set or current in absence_set:
                current += timedelta(days=1)
                continue
            lt_info = leave_map.get(current)
            lt = _leave_summary(lt_info)
            if lt == "full":
                current += timedelta(days=1)
                continue
            sessions = clock_by_emp_date.get((emp.id, current), [])
            session_set = {c.session for c in sessions}
            n = len(session_set)
            morning = {1, 2}
            afternoon = {3, 4}
            is_pending = False
            if n in (1, 3):
                is_pending = True
            elif n == 2 and not (morning <= session_set) and not (afternoon <= session_set):
                is_pending = True
            if is_pending:
                # 该员工当月补卡次数已用完(满2天)的，不再拦，那天按0工时算（不发钱）
                month_str = current.strftime("%Y-%m")
                used_in_month = sum(1 for d in emp_makeup_dates.get(emp.id, set()) if d.strftime("%Y-%m") == month_str)
                if used_in_month < 2:
                    missing = [SESSION_CN[s] for s in (1, 2, 3, 4) if s not in session_set]
                    pending_days.append({"employee": emp.name, "date": current.isoformat(), "missing": missing})
            # 宽限期内：没打卡、没请假、还没过当天下午下班的24小时 → 提示（不算旷工不发钱）
            if n == 0 and lt is None:
                day_end = datetime.combine(current, afternoon_end_time, tzinfo=THAI_TZ)
                deadline = day_end + timedelta(hours=24)
                if thai_now() <= deadline:
                    grace_days.append({"employee": emp.name, "date": current.isoformat()})
            current += timedelta(days=1)

    base.update({
        "early_return": None,
        "employees": employees, "emp_start": emp_start, "skipped_notes": skipped_notes,
        "no_hire_names": no_hire_names, "no_salary_template": no_salary_template, "no_deduction_template": no_deduction_template, "pending_days": pending_days,
        "grace_days": grace_days,
        "template_map": template_map, "deduction_template_map": deduction_template_map,
        "clock_by_emp_date": clock_by_emp_date, "leave_by_emp": leave_by_emp, "rest_by_emp": rest_by_emp, "absence_by_emp": absence_by_emp,
        "overtime_map": overtime_map, "fixed_by_emp": fixed_by_emp, "temp_by_emp": temp_by_emp,
        "early_half_time": early_half_time, "early_one_time": early_one_time, "afternoon_end_time": afternoon_end_time,
        "standard_hours": standard_hours,
        "work_sched": work_sched,
        "period_end": period_end,
    })
    return base

